const body = $json.body ?? $json;
const youtubeCommentId = String(body.youtube_comment_id ?? '').trim();
const reply = String(body.reply ?? '').trim();
if (!youtubeCommentId) throw new Error('youtube_comment_id is required');
if (!reply) throw new Error('reply is required');
if (reply.length > 2000) throw new Error('reply is too long');
return [{ json: {
  youtube_comment_id: youtubeCommentId,
  reply,
  idempotency_key: $json.headers?.['idempotency-key'] ?? youtubeCommentId
} }];

const publisher = $json.items?.[0];
if (!publisher?.id) throw new Error('The connected Google account does not have an authenticated YouTube channel');
const req = $('Validate Reply').first().json;
return [{ json: {
  ...req,
  publisher_channel_id: publisher.id,
  publisher_channel_title: publisher.snippet?.title ?? 'YouTube channel'
} }];

const body = $json.body ?? $json;

const allowed = ['connect', 'sync'];
if (!allowed.includes(body.action)) {
  throw new Error('action must be connect or sync');
}

if (!body.callback_base_url) {
  throw new Error('callback_base_url is required');
}

const callback = String(body.callback_base_url).trim().replace(/\/+$/, '');
if (!/^https?:\/\//i.test(callback)) {
  throw new Error('callback_base_url must be an absolute http(s) URL');
}

if (body.action === 'connect' && !body.target_channel) {
  throw new Error('target_channel is required for connect');
}

if (body.action === 'sync' && !body.channel_id) {
  throw new Error('channel_id is required for sync');
}

// Keep only non-secret runtime context for the 15-minute monitor.
const state = $getWorkflowStaticData('global');
state.callback_base_url = callback;
if (body.channel_id) state.channel_id = Number(body.channel_id);
if (body.youtube_channel_id) {
  state.youtube_channel_id = String(body.youtube_channel_id);
}

return [{
  json: {
    ...body,
    callback_base_url: callback
  }
}];

const raw = String($json.target_channel || '').trim();
if (!raw) throw new Error('target_channel is empty');
let value = raw;
try {
  const u = new URL(raw);
  if (!u.hostname.toLowerCase().includes('youtube.com')) throw new Error('Only YouTube channel URLs are supported');
  const parts = u.pathname.split('/').filter(Boolean);
  if (parts[0] === 'channel' && parts[1]) value = parts[1];
  else if (parts[0]?.startsWith('@')) value = parts[0];
  else value = parts[0] || raw;
} catch (e) {
  if (/^https?:\/\//i.test(raw)) throw e;
}
value = String(value).trim();
let lookup_type = 'search';
let lookup_value = value;
if (/^UC[0-9A-Za-z_-]{20,}$/.test(value)) lookup_type = 'id';
else if (value.startsWith('@')) { lookup_type = 'handle'; lookup_value = value; }
else if (/^[A-Za-z0-9._-]+$/.test(value)) { lookup_type = 'handle'; lookup_value = '@' + value.replace(/^@/, ''); }
return [{ json: { ...$json, lookup_type, lookup_value } }];

const item = $json.items?.[0];
if (!item?.id) throw new Error('Public YouTube channel not found');

const s = item.snippet ?? {};
const c = item.contentDetails ?? {};
const st = item.statistics ?? {};
const brand = item.brandingSettings?.channel ?? {};
const status = item.status ?? {};
const topics = item.topicDetails ?? {};

const thumbnail =
  s.thumbnails?.high?.url ??
  s.thumbnails?.medium?.url ??
  s.thumbnails?.default?.url ??
  null;

const state = $getWorkflowStaticData('global');
state.youtube_channel_id = item.id;
state.uploads_playlist_id = c.relatedPlaylists?.uploads ?? null;

return [{
  json: {
    youtube_channel_id: item.id,
    channel_title: s.title || 'YouTube Channel',
    channel_url: `https://www.youtube.com/channel/${item.id}`,
    custom_url: s.customUrl ?? null,
    thumbnail_url: thumbnail,
    description: s.description ?? '',
    country: s.country ?? brand.country ?? null,
    default_language: s.defaultLanguage ?? brand.defaultLanguage ?? null,
    published_at: s.publishedAt ?? null,
    uploads_playlist_id: c.relatedPlaylists?.uploads ?? null,
    subscriber_count: Number(st.subscriberCount ?? 0),
    hidden_subscriber_count: Boolean(st.hiddenSubscriberCount ?? false),
    channel_view_count: Number(st.viewCount ?? 0),
    public_video_count: Number(st.videoCount ?? 0),
    keywords: brand.keywords ?? null,
    topic_categories: topics.topicCategories ?? [],
    privacy_status: status.privacyStatus ?? null,
    made_for_kids: status.madeForKids ?? null
  }
}];

const req = $('Validate FastAPI Request').first().json;
const item = $json.items?.[0];
if (!item?.id) throw new Error('YouTube channel no longer exists or is not public');
const uploads = item.contentDetails?.relatedPlaylists?.uploads;
if (!uploads) throw new Error('Channel uploads playlist was not returned by YouTube');
const state = $getWorkflowStaticData('global');
state.callback_base_url = req.callback_base_url;
state.channel_id = Number(req.channel_id);
state.youtube_channel_id = item.id;
state.uploads_playlist_id = uploads;
return [{ json: {
  callback_base_url: req.callback_base_url,
  channel_id: Number(req.channel_id),
  youtube_channel_id: item.id,
  uploads_playlist_id: uploads,
  video_sync_mode: 'recent',
  video_limit: 50
} }];

const state = $getWorkflowStaticData('global');
const callback = String(state.callback_base_url || '').replace(/\/$/, '');
if (!callback) return [];
return [{ json: { callback_base_url: callback } }];

const state = $getWorkflowStaticData('global');
const current = $json.channel;
if (!$json.connected || !current?.id || !current?.youtube_channel_id) return [];
const uploads = current.uploads_playlist_id || state.uploads_playlist_id;
if (!uploads) throw new Error('uploads_playlist_id is missing. Reconnect this channel once with the updated workflow.');
return [{ json: {
  callback_base_url: String(state.callback_base_url).replace(/\/$/, ''),
  channel_id: Number(current.id),
  youtube_channel_id: current.youtube_channel_id,
  uploads_playlist_id: uploads,
  video_sync_mode: 'recent',
  video_limit: 50
} }];

function getContext() {
  try {
    const m = $('Build Monitor Context').first().json;
    if (m?.video_sync_mode === 'recent') return m;
  } catch {}
  return $('Build Full Sync Context').first().json;
}

const ctx = getContext();
const ids = [];

for (const input of items) {
  const body = input.json.body ?? input.json;

  for (const row of body.items ?? []) {
    const id = row.contentDetails?.videoId;

    if (id && !ids.includes(id)) {
      ids.push(id);
    }

    if (ids.length >= 50) break;
  }

  if (ids.length >= 50) break;
}

const latestIds = ids.slice(0, 50);

if (!latestIds.length) {
  return [{
    json: {
      ...ctx,
      __no_videos: true
    }
  }];
}

return [{
  json: {
    ...ctx,
    __no_videos: false,
    video_ids: latestIds,
    videos_checked_total: latestIds.length
  }
}];

function getContext() {
  try {
    const m = $('Build Monitor Context').first().json;
    if (m?.video_sync_mode === 'recent') return m;
  } catch {}
  return $('Build Full Sync Context').first().json;
}
const ctx = getContext();
const videos = [];
for (const input of items) {
  const body = input.json.body ?? input.json;
  for (const v of body.items ?? []) {
    videos.push({
      found: true,
      video_id: v.id,
      title: v.snippet?.title || 'Untitled',
      youtube_url: `https://www.youtube.com/watch?v=${v.id}`,
      thumbnail_url: v.snippet?.thumbnails?.high?.url ?? v.snippet?.thumbnails?.medium?.url ?? v.snippet?.thumbnails?.default?.url ?? null,
      description: v.snippet?.description ?? '',
      tags: v.snippet?.tags ?? [],
      channel_id: v.snippet?.channelId,
      channel_title: v.snippet?.channelTitle ?? 'Unknown',
      category_id: v.snippet?.categoryId ?? null,
      default_language: v.snippet?.defaultLanguage ?? null,
      default_audio_language: v.snippet?.defaultAudioLanguage ?? null,
      live_broadcast_content: v.snippet?.liveBroadcastContent ?? null,
      published_at: v.snippet?.publishedAt ?? null,
      duration: v.contentDetails?.duration ?? null,
      definition: v.contentDetails?.definition ?? null,
      caption_available: v.contentDetails?.caption === 'true',
      view_count: Number(v.statistics?.viewCount ?? 0),
      like_count: Number(v.statistics?.likeCount ?? 0),
      comment_count: Number(v.statistics?.commentCount ?? 0)
    });
  }
}
const output = [];
for (let i = 0; i < videos.length; i += 50) {
  output.push({ json: { ...ctx, videos: videos.slice(i, i + 50) } });
}
return output.length ? output : [{ json: { ...ctx, __no_videos: true } }];

function getContext() {
  try {
    const m = $('Build Monitor Context').first().json;
    if (m?.video_sync_mode === 'recent') return m;
  } catch {}
  return $('Build Full Sync Context').first().json;
}
return [{ json: getContext() }];

const ctx = $('Prepare Comment Poll').first().json;

let latestVideoIds = [];

try {
  latestVideoIds = $('Batch Video IDs').first().json.video_ids ?? [];
} catch {}

const latestVideoSet = new Set(
  latestVideoIds.map((id) => String(id))
);

const output = [];
let fetched = 0;
let skippedOutsideLatestVideos = 0;

for (const input of items) {
  const body = input.json.body ?? input.json;

  for (const thread of body.items ?? []) {
    const top = thread.snippet?.topLevelComment;
    const s = top?.snippet;

    if (
      !top?.id ||
      !s?.videoId ||
      (!s?.textOriginal && !s?.textDisplay)
    ) {
      continue;
    }

    fetched += 1;

    // IMPORTANT:
    // CreatorLoop v8 only processes comments that belong to the
    // latest 50 videos collected by Batch Video IDs in this sync.
    if (!latestVideoSet.has(String(s.videoId))) {
      skippedOutsideLatestVideos += 1;
      continue;
    }

    output.push({
      json: {
        event_type: 'youtube.comment.received',
        source: 'youtube',
        monitored_channel_id: ctx.youtube_channel_id,

        comment: {
          youtube_comment_id: top.id,
          youtube_thread_id: thread.id,
          video_id: s.videoId,
          author_name: s.authorDisplayName || 'YouTube viewer',
          author_channel_id: s.authorChannelId?.value ?? null,
          author_profile_image_url:
            s.authorProfileImageUrl ?? null,
          author_channel_url: s.authorChannelUrl ?? null,
          text: s.textOriginal ?? s.textDisplay ?? '',
          like_count: Number(s.likeCount ?? 0),
          reply_count: Number(
            thread.snippet?.totalReplyCount ?? 0
          ),
          can_reply: thread.snippet?.canReply !== false,
          is_public: thread.snippet?.isPublic !== false,
          published_at: s.publishedAt,
          updated_at: s.updatedAt ?? s.publishedAt
        },

        // The video is guaranteed to be one of the latest-50 IDs.
        // FastAPI already stored/upserted those videos earlier
        // in the same sync.
        video: {
          found: false,
          video_id: s.videoId
        },

        ingestion: {
          fetched_at: new Date().toISOString(),
          pipeline:
            'creatorloop-n8n-youtube-monitor-v8'
        }
      }
    });
  }
}

if (!output.length) {
  return [{
    json: {
      ...ctx,
      __no_comments: true,
      comments_fetched: fetched,
      comments_eligible: 0,
      comments_skipped_outside_latest_videos:
        skippedOutsideLatestVideos
    }
  }];
}

return output;

const ctx = $('Prepare Comment Poll').first().json;
let delivered = 0;
let suggested = 0;
let unmet = 0;
for (const input of items) {
  const body = input.json.body ?? input.json;
  if (body.__no_comments) continue;
  delivered += 1;
  if (body.outcome === 'reply_suggested') suggested += 1;
  if (body.outcome === 'unmet_demand') unmet += 1;
}
return [{ json: { ...ctx, comments_delivered: delivered, replies_suggested: suggested, unmet_demand: unmet } }];

const req = $('Validate FastAPI Request').first().json;
const current = $json.channel;

if (!$json.connected || !current?.id || !current?.youtube_channel_id) {
  throw new Error('FastAPI has no connected YouTube channel');
}

if (Number(current.id) !== Number(req.channel_id)) {
  throw new Error(
    `Requested channel_id ${req.channel_id} does not match current channel ${current.id}`
  );
}

return [{
  json: {
    callback_base_url: req.callback_base_url,
    channel_id: Number(current.id),
    youtube_channel_id: current.youtube_channel_id
  }
}];
